}

import zlib from 'node:zlib';
function main(): void {
  const input = Buffer.from('hello world hello world');
  zlib.gzip(input, (e: any, packed: Buffer) => {
    zlib.gunzip(packed, (e2: any, plain: Buffer) => {
      setTimeout(() => {
        console.log('deep', e === null, e2 === null, plain.length === input.length);
      }, 1);
    });
    const direct = e === null;
    setTimeout(() => { console.log('mid', e === null, direct); }, 1);
  });
}

import net from 'node:net';
function main(): void {
  const server = net.createServer((socket: any) => {
    socket.on('data', (d: any) => { console.log('data', String(d)); socket.end('bye'); });
    socket.on('error', (e: any) => console.log('err', e && e.code));
  });
  server.listen(0, '127.0.0.1', () => {
    const port = (server.address() as any).port;
    const c = net.connect(port, '127.0.0.1', () => c.write('hello'));
    c.on('data', (d: any) => { console.log('client got', String(d)); });
    c.on('close', () => { console.log('closed'); server.close(); });
  });
}

import { Worker } from 'node:worker_threads';
async function main(): Promise<void> {
  const worker = new Worker(`const { parentPort } = require('node:worker_threads'); parentPort.on('message', () => {}); parentPort.unref(); parentPort.postMessage('ready');`, { eval: true });
  const log: string[] = [];
  worker.on('message', (v: any) => { log.push('message ' + v); });
  const code: number = await new Promise<number>((resolve) => { worker.on('exit', (c: number) => { resolve(c); }); });
  log.push('exit ' + code);
  console.log(log.join('|'));
}

import { Worker, setEnvironmentData } from 'node:worker_threads';
async function main(): Promise<void> {
  setEnvironmentData('w2.key', { a: 1 });
  const worker = new Worker(`const { parentPort, getEnvironmentData } = require('node:worker_threads'); parentPort.postMessage(JSON.stringify(getEnvironmentData('w2.key')) + ' ' + typeof getEnvironmentData('missing'));`, { eval: true });
  const text: string = await new Promise<string>((resolve) => { worker.once('message', (v: any) => { resolve(String(v)); }); });
  console.log(text);
  await worker.terminate();
}

import { Worker } from 'node:worker_threads';
async function main(): Promise<void> {
  const worker = new Worker(`const { parentPort } = require('node:worker_threads'); let text = ''; process.stdin.setEncoding('utf8'); process.stdin.on('data', (c) => { text += c; }); process.stdin.on('end', () => { parentPort.postMessage('got ' + text); });`, { eval: true, stdin: true });
  const log: string[] = [];
  worker.on('message', (v: any) => { log.push(String(v)); });
  worker.stdin!.write('abc');
  worker.stdin!.end('def');
  const code: number = await new Promise<number>((resolve) => { worker.on('exit', (c: number) => { resolve(c); }); });
  log.push('exit ' + code);
  console.log(log.join('|'));
}

