import { EventEmitter } from 'node:events';
function setup(app: any): void { const f = () => {}; app.on('b', f).on('c', f); }
function chained(app: any): number { const f = () => {}; const k = app.on('x', f).on('y', f); return k.listenerCount('y'); }
function make(e: any): any { const f = () => {}; return e.on('p', f).on('q', f); }
function use(x: any): number { return x.listenerCount('q'); }
function main(): void {
  const e: any = new EventEmitter();
  setup(e);
  console.log(e.listenerCount('c'), chained(e), use(make(e)), make(e) === e);
}

import { EventEmitter } from 'node:events';
import { Readable, PassThrough } from 'node:stream';
function main(): void {
  const e: any = new EventEmitter();
  const f = () => {};
  const g = () => { const k: any = e.on('x', f).on('y', f); return k.listenerCount('x'); };
  console.log(g());
  const r: any = new Readable({ read() {} });
  const r2: any = r.setEncoding('utf8').pause().resume();
  console.log(r2 === r, r2.readableFlowing);
  const p: any = new PassThrough();
  const p2: any = p.setEncoding('utf8').setMaxListeners(20);
  console.log(p2 === p, p2.getMaxListeners());
  const arr: any[] = [e.on('p', f).on('q', f)];
  const o: any = { held: e.on('m', f).on('n', f) };
  console.log(arr[0] === e, arr[0].listenerCount('q'), o.held === e, o.held.listenerCount('n'));
}

