import assert from "node:assert";

function attempt(label: string, run: () => void): void {
  try {
    run();
    console.log(label, "ok");
  } catch (e: any) {
    console.log(label, e.name, e.code, e.operator, JSON.stringify(e.message));
  }
}

function main(): void {
  attempt("ifError null", () => assert.ifError(null));
  attempt("ifError undefined", () => assert.ifError(undefined));
  attempt("ifError error", () => assert.ifError(new Error("boom")));
  attempt("ifError string", () => assert.ifError("str"));
  attempt("ifError zero", () => assert.ifError(0));
  attempt("match ok", () => assert.match("abc", /b/));
  attempt("match fail", () => assert.match("abc", /x/));
  attempt("match custom", () => assert.match("abc", /x/, "custom"));
  attempt("match number", () => assert.match(5 as any, /x/));
  attempt("doesNotMatch ok", () => assert.doesNotMatch("abc", /x/));
  attempt("doesNotMatch fail", () => assert.doesNotMatch("abc", /b/));
}

